  "style-class": "'use client';\n\nimport React, { useState } from 'react';\nimport { Button, Flex, Modal } from '@ceebee/ui/client';\nimport type { GetProp, ModalProps } from '@ceebee/ui/client';\nimport { createStaticStyles } from 'antd-style';\n\nconst lineStyle: React.CSSProperties = {\n  lineHeight: '28px',\n};\n\nconst sharedContent = (\n  <>\n    <div style={lineStyle}>\n      Following the Ceebee UI specification, we developed a React component library that contains a\n      set of high quality components and demos for building rich, interactive user interfaces.\n    </div>\n    <div style={lineStyle}>🌈 Enterprise-class UI designed for web applications.</div>\n    <div style={lineStyle}>📦 A set of high-quality React components out of the box.</div>\n    <div style={lineStyle}>🛡 Written in TypeScript with predictable static types.</div>\n    <div style={lineStyle}>⚙️ Whole package of design resources and development tools.</div>\n    <div style={lineStyle}>🌍 Internationalization support for dozens of languages.</div>\n    <div style={lineStyle}>🎨 Powerful theme customization in every detail.</div>\n  </>\n);\n\nconst classNames = createStaticStyles(({ css }) => ({\n  container: css`\n    border-radius: 10px;\n    padding: 10px;\n  `,\n}));\n\nconst styles: ModalProps['styles'] = {\n  mask: {\n    backgroundImage: `linear-gradient(to top, #18181b 0, rgba(21, 21, 22, 0.2) 100%)`,\n  },\n};\n\nconst stylesFn: ModalProps['styles'] = (info): GetProp<ModalProps, 'styles', 'Return'> => {\n  if (info.props.footer) {\n    return {\n      container: {\n        borderRadius: 14,\n        border: '1px solid #ccc',\n        padding: 0,\n        overflow: 'hidden',\n      },\n      header: {\n        padding: 16,\n      },\n      body: {\n        padding: 16,\n      },\n      footer: {\n        padding: '16px 10px',\n        backgroundColor: '#fafafa',\n      },\n    };\n  }\n  return {};\n};\n\nconst App: React.FC = () => {\n  const [modalOpen, setModalOpen] = useState(false);\n  const [modalFnOpen, setModalFnOpen] = useState(false);\n\n  const sharedProps: ModalProps = {\n    centered: true,\n    classNames,\n  };\n\n  const footer: React.ReactNode = (\n    <>\n      <Button\n        onClick={() => setModalFnOpen(false)}\n        styles={{ root: { borderColor: '#ccc', color: '#171717', backgroundColor: '#fff' } }}\n      >\n        Cancel\n      </Button>\n      <Button\n        type=\"primary\"\n        styles={{ root: { backgroundColor: '#171717' } }}\n        onClick={() => setModalOpen(true)}\n      >\n        Submit\n      </Button>\n    </>\n  );\n\n  return (\n    <Flex gap=\"medium\">\n      <Button onClick={() => setModalOpen(true)}>Open Style Modal</Button>\n      <Button type=\"primary\" onClick={() => setModalFnOpen(true)}>\n        Open Function Modal\n      </Button>\n      <Modal\n        {...sharedProps}\n        footer={null}\n        title=\"Custom Style Modal\"\n        styles={styles}\n        open={modalOpen}\n        onOk={() => setModalOpen(false)}\n        onCancel={() => setModalOpen(false)}\n      >\n        {sharedContent}\n      </Modal>\n      <Modal\n        {...sharedProps}\n        footer={footer}\n        title=\"Custom Function Modal\"\n        styles={stylesFn}\n        mask={{ enabled: true, blur: true }}\n        open={modalFnOpen}\n        onOk={() => setModalFnOpen(false)}\n        onCancel={() => setModalFnOpen(false)}\n      >\n        {sharedContent}\n      </Modal>\n    </Flex>\n  );\n};\n\nexport default App;\n",
  "width": "'use client';\n\nimport React, { useState } from 'react';\nimport { Button, Flex, Modal } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const [open, setOpen] = useState(false);\n  const [openResponsive, setOpenResponsive] = useState(false);\n\n  return (\n    <Flex vertical gap=\"medium\" align=\"flex-start\">\n      {/* Basic */}\n      <Button type=\"primary\" onClick={() => setOpen(true)}>\n        Open Modal of 1000px width\n      </Button>\n      <Modal\n        title=\"Modal 1000px width\"\n        centered\n        open={open}\n        onOk={() => setOpen(false)}\n        onCancel={() => setOpen(false)}\n        width={1000}\n      >\n        <p>some contents...</p>\n        <p>some contents...</p>\n        <p>some contents...</p>\n      </Modal>\n\n      {/* Responsive */}\n      <Button type=\"primary\" onClick={() => setOpenResponsive(true)}>\n        Open Modal of responsive width\n      </Button>\n      <Modal\n        title=\"Modal responsive width\"\n        centered\n        open={openResponsive}\n        onOk={() => setOpenResponsive(false)}\n        onCancel={() => setOpenResponsive(false)}\n        width={{\n          xs: '90%',\n          sm: '80%',\n          md: '70%',\n          lg: '60%',\n          xl: '50%',\n          xxl: '40%',\n        }}\n      >\n        <p>some contents...</p>\n        <p>some contents...</p>\n        <p>some contents...</p>\n      </Modal>\n    </Flex>\n  );\n};\n\nexport default App;\n"
